        deadline_micros: source.deadline_micros,
        observation: source.observation.clone(),
        candidates: source.candidates.clone(),
    }
}

fn invalid(error: impl std::fmt::Display) -> AgentdError {
    AgentdError::Invalid(error.to_string())
}

