fn opened(root: &Path, name: &str, create: bool) -> anyhow::Result<File> {
    let mut options = OpenOptions::new();
    options.read(true).write(true).mode(0o600);
    if create {
        options.create_new(true);
    }
    Ok(options.open(root.join(name))?)
